    "html": "<!-- folio-greeting: Dear colleague, (this body carries its own greeting) -->\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" data-folio-fragment=\"RP-Statistics\" data-folio-v3b=\"1\">\n\n<tbody><tr><td style=\"\"><p style=\"margin:0 0 0 0;font-weight:600;font-size:17px;line-height:24px;font-family:Outfit, 'Segoe UI', Arial, sans-serif;color:#1B1A1A\">Dear colleague,</p></td></tr><tr><td style=\"padding-top:14px\"><p style=\"margin:0 0 0 0;font-weight:400;font-size:15px;line-height:24px;font-family:Verdana, sans-serif;color:#1B1A1A\">Comprehensive overview of activities, tasks and performance generated by {{profileName}}.</p></td></tr><tr><td style=\"padding-top:20px\"><table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" class=\"tiles\" style=\"width:100%;border-collapse:separate;border-spacing:8px 0;table-layout:fixed;margin:6px -8px 0 -8px\">\n        <tbody>\n          <tr>\n            <td class=\"tile\" style=\"padding:14px;background:#F5F4F4;border-radius:10px;vertical-align:top\"><span style=\"display:block;font-weight:700;font-size:12px;line-height:16px;font-family:Verdana, sans-serif;letter-spacing:.6px;text-transform:uppercase;color:#5F5C5D\">Total records</span><span style=\"display:block;margin-top:6px;font-weight:700;font-size:22px;line-height:28px;font-family:Outfit, 'Segoe UI', Arial, sans-serif;word-break:break-word;color:#1B1A1A\">{{total}}</span></td>\n            <td class=\"tile\" style=\"padding:14px;background:#E6F7ED;border-radius:10px;vertical-align:top\"><span style=\"display:block;font-weight:700;font-size:12px;line-height:16px;font-family:Verdana, sans-serif;letter-spacing:.6px;text-transform:uppercase;color:#0D7234\">Completed / assigned</span><span style=\"display:block;margin-top:6px;font-weight:700;font-size:22px;line-height:28px;font-family:Outfit, 'Segoe UI', Arial, sans-serif;word-break:break-word;color:#1B1A1A\">{{completed}}</span></td>\n            <td class=\"tile\" style=\"padding:14px;background:#EAF3EF;border-radius:10px;vertical-align:top\"><span style=\"display:block;font-weight:700;font-size:12px;line-height:16px;font-family:Verdana, sans-serif;letter-spacing:.6px;text-transform:uppercase;color:#05583B\">Assigned coverage</span><span style=\"display:block;margin-top:6px;font-weight:700;font-size:22px;line-height:28px;font-family:Outfit, 'Segoe UI', Arial, sans-serif;word-break:break-word;color:#1B1A1A\">{{coverage}}</span></td>\n          </tr>\n        </tbody>\n      </table></td></tr><tr><td style=\"padding-top:14px\"><table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin:8px 0 2px\"><tbody><tr><td width=\"18\" style=\"width:18px;vertical-align:middle;font-size:0;line-height:0\"><table role=\"presentation\" width=\"18\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tbody><tr><td width=\"18\" height=\"3\" bgcolor=\"#17B255\" style=\"width:18px;height:3px;background:#17B255;font-size:0;line-height:0\">&nbsp;</td></tr></tbody></table></td><td style=\"padding-left:10px;font-family:Outfit,'Segoe UI',Arial,sans-serif;font-size:12px;line-height:16px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:#05583B;white-space:nowrap\">Status breakdown</td></tr></tbody></table></td></tr><tr><td style=\"padding-top:14px\"><table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"width:100%;border-collapse:collapse;table-layout:fixed\">\n        <tbody>\n          <!--each:bars-->\n          \n            <tr>\n              <td style=\"width:30%;padding:6px 10px 6px 0;font-weight:400;font-size:12px;line-height:18px;font-family:Verdana, sans-serif;color:#373435\">{{row.label}}</td>\n              <td style=\"padding:6px 0\">\n                <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"width:100%;border-collapse:collapse;table-layout:fixed\"><tbody><tr>\n                  <td style=\"width:{{row.pct}}%;height:12px;background:#1A7250;border-radius:6px 0 0 6px\"></td>\n                  <td style=\"height:12px;background:#EAF3EF;border-radius:0 6px 6px 0\"></td>\n                </tr></tbody></table>\n              </td>\n              <td style=\"width:52px;padding:6px 0 6px 10px;text-align:right;font-weight:700;font-size:12px;line-height:18px;font-family:Verdana, sans-serif;color:#1B1A1A\">{{row.count}}</td>\n            </tr>\n          <!--/each:bars-->\n\n          \n        </tbody>\n      </table></td></tr><tr><td style=\"padding-top:14px\"><table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin:8px 0 2px\"><tbody><tr><td width=\"18\" style=\"width:18px;vertical-align:middle;font-size:0;line-height:0\"><table role=\"presentation\" width=\"18\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tbody><tr><td width=\"18\" height=\"3\" bgcolor=\"#17B255\" style=\"width:18px;height:3px;background:#17B255;font-size:0;line-height:0\">&nbsp;</td></tr></tbody></table></td><td style=\"padding-left:10px;font-family:Outfit,'Segoe UI',Arial,sans-serif;font-size:12px;line-height:16px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:#05583B;white-space:nowrap\">Records</td></tr></tbody></table></td></tr><tr><td style=\"padding-top:14px\"><table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" class=\"dt\" style=\"width:100%;border-collapse:collapse;table-layout:fixed\">\n        <thead>\n          <tr style=\"background:#F5F4F4\">\n            <th style=\"width:28px;padding:8px 6px;text-align:left;font-weight:700;font-size:12px;line-height:16px;font-family:Verdana, sans-serif;color:#5F5C5D\">#</th>\n            <th style=\"padding:8px 6px;text-align:left;font-weight:700;font-size:12px;line-height:16px;font-family:Verdana, sans-serif;color:#5F5C5D\">Title</th>\n            <th style=\"width:80px;padding:8px 6px;text-align:left;font-weight:700;font-size:12px;line-height:16px;font-family:Verdana, sans-serif;color:#5F5C5D\">Priority</th>\n            <th style=\"width:84px;padding:8px 6px;text-align:left;font-weight:700;font-size:12px;line-height:16px;font-family:Verdana, sans-serif;color:#5F5C5D\">Status</th>\n            <th style=\"width:44px;padding:8px 6px;text-align:left;font-weight:700;font-size:12px;line-height:16px;font-family:Verdana, sans-serif;color:#5F5C5D\">Link</th>\n          </tr>\n        </thead>\n        <tbody>\n          <!--each:rows-->\n          \n            <tr>\n              <td style=\"padding:9px 6px;border-bottom:1px solid #E8E6E7;font-weight:400;font-size:13px;line-height:19px;font-family:Verdana, sans-serif;color:#5F5C5D\">{{row.n}}</td>\n              <td style=\"padding:9px 6px;border-bottom:1px solid #E8E6E7;font-weight:400;font-size:13px;line-height:19px;font-family:Verdana, sans-serif;color:#1B1A1A\">{{row.title}}<br><span style=\"color:#5F5C5D\">{{row.kind}} · {{row.category}} · {{row.assignedTo}} · {{row.date}}</span></td>\n              <td style=\"padding:9px 6px;border-bottom:1px solid #E8E6E7;font-weight:400;font-size:13px;line-height:19px;font-family:Verdana, sans-serif\">{{row.priority}}</td>\n              <td style=\"padding:9px 6px;border-bottom:1px solid #E8E6E7;font-weight:400;font-size:13px;line-height:19px;font-family:Verdana, sans-serif\">{{row.status}}</td>\n              <td style=\"padding:9px 6px;border-bottom:1px solid #E8E6E7;font-weight:700;font-size:13px;line-height:19px;font-family:Verdana, sans-serif\"><a href=\"{{row.url}}\" style=\"color:#05583B\">View</a></td>\n            </tr>\n          <!--/each:rows-->\n\n          \n        </tbody>\n      </table></td></tr>\n</tbody></table>"
